// Example: DecodeStream usage
ctx := context.Background()
stream, err := client.Completions.Stream(ctx, req)
if err != nil { return err }
// Decode into typed struct using generics helper
for obj := range sdk.DecodeStream[CompletionResponse](ctx, stream) {
    if obj.Err != nil { log.Printf("decode error: %v", obj.Err); continue }
    fmt.Printf("content: %s", obj.Value.Choices[0].Text)
}
